// Take the uploaded PDF (whatever the binary key is called) and expose it as base64 JSON
// so the HTTP Request node can embed it in the Anthropic document block.
const item = $input.first();
const key = Object.keys(item.binary || {})[0];
if (!key) throw new Error('No file uploaded');
const bin = item.binary[key];
if ((bin.mimeType || '').toLowerCase() !== 'application/pdf') {
  throw new Error(`Expected a PDF, got ${bin.mimeType}`);
}
const buf = await this.helpers.getBinaryDataBuffer(0, key);
return [{
  json: {
    fileName: bin.fileName,
    sizeKB: Math.round(buf.length / 1024),
    receivedAt: new Date().toISOString(),
    pdfBase64: buf.toString('base64')
  },
  binary: { pack: bin }
}];

