// Parse the model's JSON, sanity-check page coverage, emit one item per document.
const resp = $input.first().json;
const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const clean = text.replace(/```json|```/g, '').trim();
let parsed;
try { parsed = JSON.parse(clean); }
catch (e) { throw new Error('Classifier did not return valid JSON: ' + clean.slice(0, 300)); }

const docs = parsed.documents || [];
const pageCount = parsed.page_count || 0;

// coverage check: every page exactly once
const seen = new Map();
for (const d of docs) for (const p of (d.pages || [])) seen.set(p, (seen.get(p) || 0) + 1);
const missing = [], dup = [];
for (let p = 1; p <= pageCount; p++) {
  const n = seen.get(p) || 0;
  if (n === 0) missing.push(p);
  if (n > 1) dup.push(p);
}

// cost estimate (Sonnet 5 list price: $2 / $10 per MTok)
const u = resp.usage || {};
const costUsd = ((u.input_tokens || 0) * 2 + (u.output_tokens || 0) * 10) / 1e6;

const source = $('PreparePDF').first().json;
return docs.map(d => ({
  json: {
    file_name: source.fileName,
    doc_id: d.doc_id,
    pages: d.pages,
    page_range: d.pages.length > 1 ? `${d.pages[0]}-${d.pages[d.pages.length - 1]}` : String(d.pages[0]),
    doc_type: d.doc_type,
    vendor_or_bank: d.vendor_or_bank,
    vendor_country: d.vendor_country,
    language: d.language,
    currency: d.currency,
    scanned: !!d.scanned,
    confidence: d.confidence,
    notes: d.notes || '',
    _pack: {
      page_count: pageCount,
      documents_found: docs.length,
      coverage_ok: missing.length === 0 && dup.length === 0,
      missing_pages: missing,
      duplicate_pages: dup,
      model: resp.model,
      input_tokens: u.input_tokens,
      output_tokens: u.output_tokens,
      cost_usd: Number(costUsd.toFixed(4))
    }
  }
}));

// Build one small PDF per classified document using pdf-lib (only that document's pages).
const { PDFDocument } = require('pdf-lib');
const srcB64 = $('PreparePDF').first().json.pdfBase64;
const src = await PDFDocument.load(Buffer.from(srcB64, 'base64'));
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const pdf = await PDFDocument.create();
  const pages = await pdf.copyPages(src, d.pages.map(p => p - 1));
  pages.forEach(p => pdf.addPage(p));
  const bytes = Buffer.from(await pdf.save());
  const fileName = `doc${String(d.doc_id).padStart(2, '0')}_p${d.page_range}_${d.doc_type}.pdf`;
  out.push({
    json: { ...d, doc_file_name: fileName, doc_pdf_kb: Math.round(bytes.length / 1024), doc_pdf_base64: bytes.toString('base64') },
    binary: { doc_pdf: await this.helpers.prepareBinaryData(bytes, fileName, 'application/pdf') }
  });
}
return out;

