// Per item: parse the extraction JSON and merge with classification + cost.
const resp = $input.item.json;
const cls = $('SplitPDF').item.json;
const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const clean = text.replace(/```json|```/g, '').trim();
let ex;
try { ex = JSON.parse(clean); }
catch (e) { ex = { _parse_error: 'Model did not return valid JSON: ' + clean.slice(0, 200) }; }
const u = resp.usage || {};
const cost = ((u.input_tokens || 0) * 2 + (u.output_tokens || 0) * 10) / 1e6;
const { doc_pdf_base64, ...clsRest } = cls;
return {
  json: {
    ...clsRest,
    doc_type: ex.doc_type || cls.doc_type,
    extracted: ex,
    _extract: { model: resp.model, input_tokens: u.input_tokens, output_tokens: u.output_tokens, cost_usd: Number(cost.toFixed(4)) }
  },
  binary: $('SplitPDF').item.binary
};

// Deterministic validation. The AI extracts, arithmetic decides.
const VAT_RATES = { LT:[0,9,21], LV:[0,5,12,21], EE:[0,9,22,24], PL:[0,5,8,23], DE:[0,7,19], AT:[0,10,13,20],
  SE:[0,6,12,25], DK:[0,25], FI:[0,10,14,25.5], NO:[0,12,15,25], IE:[0,9,13.5,23], NL:[0,9,21], BE:[0,6,12,21],
  FR:[0,5.5,10,20], ES:[0,4,10,21], IT:[0,4,5,10,22], GB:[0,5,20], US:[0] };
const EU = new Set(['LT','LV','EE','PL','DE','AT','SE','DK','FI','IE','NL','BE','FR','ES','IT','PT','CZ','SK','HU','RO','BG','HR','SI','GR','CY','MT','LU']);
const TOL = 0.02;
const num = v => (v === null || v === undefined || v === '') ? null : Number(v);
const near = (a, b, t = TOL) => a !== null && b !== null && Math.abs(a - b) <= t;

const d = $input.item.json;
const ex = d.extracted || {};
const reasons = [];   // -> needs_review
const tags = [];      // informational, not errors
const checks = {};

if (ex._parse_error) reasons.push(ex._parse_error);

const isDoc = ['invoice', 'utility_bill', 'receipt', 'other'].includes(d.doc_type);
if (isDoc && !ex._parse_error) {
  const net = num(ex.net_total), vat = num(ex.vat_amount), gross = num(ex.gross_total), rate = num(ex.vat_rate_percent);
  const country = (ex.vendor_country || d.vendor_country || '').toUpperCase();

  // 1. line items sum to net (invoices) or gross (receipts, VAT-inclusive)
  if (Array.isArray(ex.line_items) && ex.line_items.length) {
    const sum = ex.line_items.reduce((s, li) => s + (num(li.amount) || 0), 0);
    checks.line_items_sum = Number(sum.toFixed(2));
    if (!near(sum, d.doc_type === 'receipt' ? gross : net) && !near(sum, gross)) reasons.push(`line items sum ${sum.toFixed(2)} ≠ ${d.doc_type === 'receipt' ? 'gross ' + gross : 'net ' + net}`);
  }
  // 2. net + VAT = gross
  checks.net_plus_vat = net !== null && vat !== null ? Number((net + vat).toFixed(2)) : null;
  if (!near(checks.net_plus_vat, gross)) reasons.push(`net ${net} + VAT ${vat} = ${checks.net_plus_vat} ≠ gross ${gross}`);
  // 3. VAT amount matches rate
  if (rate !== null && net !== null) {
    checks.expected_vat = Number((net * rate / 100).toFixed(2));
    if (!near(checks.expected_vat, vat)) reasons.push(`VAT ${vat} ≠ ${rate}% of ${net} (= ${checks.expected_vat})`);
  }
  // 4. rate plausible for the country
  if (rate !== null && country && VAT_RATES[country] && !VAT_RATES[country].includes(rate)) {
    reasons.push(`VAT rate ${rate}% is not a ${country} rate (${VAT_RATES[country].join('/')}%)`);
  }
  // 5. 0% from an EU vendor needs a reverse-charge clause
  if (rate === 0 && EU.has(country) && country !== 'LT' && !ex.reverse_charge) {
    reasons.push(`0% VAT from EU vendor (${country}) without reverse-charge clause`);
  }
  if (ex.reverse_charge) tags.push('reverse charge — account for VAT locally (VAT return)');
  if (country === 'US') tags.push('non-EU vendor — no VAT, check import VAT rules');
  if ((ex.currency || d.currency) && (ex.currency || d.currency) !== 'EUR') tags.push(`foreign currency ${ex.currency || d.currency} — FX left to accountant`);
  // 6. identifiers & dates
  const dateStr = ex.invoice_date || ex.date;
  const dt = dateStr ? new Date(dateStr) : null;
  if (!dt || isNaN(dt)) reasons.push('date missing or unparseable');
  else if (dt > new Date()) reasons.push(`date ${dateStr} is in the future`);
  if (d.doc_type !== 'receipt' && !ex.invoice_number) reasons.push('invoice number missing');
  if (!ex.vendor_name) reasons.push('vendor name missing');
}

if (d.doc_type === 'bank_statement' && !ex._parse_error) {
  const open = num(ex.opening_balance), close = num(ex.closing_balance);
  const tx = Array.isArray(ex.transactions) ? ex.transactions : [];
  const sum = tx.reduce((s, t) => s + (num(t.amount) || 0), 0);
  checks.transaction_count = tx.length;
  checks.opening_plus_transactions = open !== null ? Number((open + sum).toFixed(2)) : null;
  if (!near(checks.opening_plus_transactions, close)) reasons.push(`opening ${open} + transactions ${sum.toFixed(2)} ≠ closing ${close}`);
  if (!tx.length) reasons.push('no transactions extracted');
  tags.push('bank statement — reconcile against invoices in this pack');
}

// scanned source: informational unless the model itself flagged poor OCR
if (d.scanned) tags.push('scanned source');
if (ex.ocr_quality === 'poor') reasons.push('model reported poor OCR quality — verify digits');

const status = reasons.length ? 'needs_review' : 'pass';
return { json: { ...d, status, review_reasons: reasons, tags, checks }, binary: $input.item.binary };

// Rename + file each document PDF on disk, and build the flat sheet row.
const fs = require('fs');
const path = require('path');
const cfg = $('Config').first().json;
const root = cfg.output_root || '/files';
const runId = new Date().toISOString().slice(0, 19).replace('T', ' ');
const slug = s => (s || 'unknown').toString().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase().slice(0, 40);

const out = [];
for (const item of $input.all()) {
  const d = item.json, ex = d.extracted || {};
  const date = ex.invoice_date || ex.date || ex.period_to || 'undated';
  const number = ex.invoice_number || ex.receipt_number || (ex.period_from ? `${ex.period_from}_${ex.period_to}` : null) || `doc${d.doc_id}`;
  const vendor = ex.vendor_name || ex.bank_name || d.vendor_or_bank;
  const folder = d.status === 'pass' ? path.join(root, 'sorted', d.doc_type) : path.join(root, 'needs-review');
  const fileName = `${date}_${slug(vendor)}_${slug(number)}.pdf`;
  fs.mkdirSync(folder, { recursive: true });
  const buf = await this.helpers.getBinaryDataBuffer($input.all().indexOf(item), 'doc_pdf');
  fs.writeFileSync(path.join(folder, fileName), buf);

  out.push({ json: {
    run_id: runId,
    date,
    doc_type: d.doc_type,
    vendor,
    country: ex.vendor_country || d.vendor_country || '',
    number,
    currency: ex.currency || d.currency || '',
    net: ex.net_total ?? ex.opening_balance ?? '',
    vat: ex.vat_amount ?? '',
    gross: ex.gross_total ?? ex.closing_balance ?? '',
    category: ex.suggested_expense_category || (d.doc_type === 'bank_statement' ? 'Bank' : ''),
    status: d.status,
    review_reasons: (d.review_reasons || []).join(' | '),
    tags: (d.tags || []).join(' | '),
    pages: d.page_range,
    scanned: d.scanned ? 'yes' : 'no',
    file_path: path.join(folder, fileName).replace(root, ''),
    // carried for Summary
    _pack: d._pack, _extract: d._extract, doc_id: d.doc_id, file_name: d.file_name, vendor_or_bank: d.vendor_or_bank, page_range: d.page_range, extracted: ex
  }});
}
return out;

// One summary item for the run (demo talking points + the email).
const items = $('FileDocuments').all().map(i => i.json);
const pack = items[0]?._pack || {};
const byCurrency = {};
let extractCost = 0;
for (const d of items) {
  extractCost += d._extract?.cost_usd || 0;
  const ex = d.extracted || {};
  if (['invoice','utility_bill','receipt','other'].includes(d.doc_type) && ex.gross_total != null) {
    const c = ex.currency || d.currency || '?';
    byCurrency[c] = Number(((byCurrency[c] || 0) + Number(ex.gross_total)).toFixed(2));
  }
}
const review = items.filter(d => d.status === 'needs_review').map(d => ({ doc_id: d.doc_id, pages: d.page_range, vendor: d.vendor_or_bank, reasons: d.review_reasons }));
const totalCost = Number(((pack.cost_usd || 0) + extractCost).toFixed(4));
const runId = items[0]?.run_id;
return [{ json: {
  run_id: runId,
  file_name: items[0]?.file_name,
  pages: pack.page_count, documents: items.length,
  auto_pass: items.length - review.length, needs_review: review.length,
  review_items: review,
  gross_totals_by_currency: byCurrency,
  types: items.reduce((m, d) => { m[d.doc_type] = (m[d.doc_type] || 0) + 1; return m; }, {}),
  cost_usd: { classify: pack.cost_usd, extract: Number(extractCost.toFixed(4)), total: totalCost },
  one_liner: `Processed ${items[0]?.file_name}: ${items.length} documents — ${items.length - review.length} auto-validated, ${review.length} flagged for review. AI cost $${totalCost}.`
}}];

// Write the run summary next to the sorted folders (and build the email text).
const fs = require('fs');
const path = require('path');
const cfg = $('Config').first().json;
const s = $input.first().json;
const lines = [
  s.one_liner, '',
  `Documents: ${s.documents} (${Object.entries(s.types).map(([k, v]) => `${v} ${k}`).join(', ')})`,
  `Auto-validated: ${s.auto_pass}   Needs review: ${s.needs_review}`,
  `Totals: ${Object.entries(s.gross_totals_by_currency).map(([c, v]) => `${v.toFixed(2)} ${c}`).join(' · ')}`,
  '', 'Flagged for review:',
  ...(s.review_items.length ? s.review_items.map(r => `  • pages ${r.pages} — ${r.vendor}: ${Array.isArray(r.reasons) ? r.reasons.join('; ') : r.reasons}`) : ['  (none)']),
  '', `Files: ${cfg.output_root}/sorted/<type>/ and ${cfg.output_root}/needs-review/`,
  `AI cost this run: $${s.cost_usd.total}`
];
const text = lines.join('\n');
fs.mkdirSync(cfg.output_root, { recursive: true });
fs.writeFileSync(path.join(cfg.output_root, 'last-run-summary.txt'), text);
fs.writeFileSync(path.join(cfg.output_root, 'last-run-summary.json'), JSON.stringify(s, null, 2));
return [{ json: { ...s, email_subject: `Processed ${s.file_name}: ${s.auto_pass} filed, ${s.needs_review} to review`, email_text: text } }];
